#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-07-27

# CI wrapper around audit-skill-permissions.sh.
#
# WHY THIS EXISTS: the audit reports two unrelated conditions and CI must treat
# them differently.
#   exit 2 = COVERAGE VIOLATION. A skill instructs a tool its allowed-tools
#            omits, so the skill is broken at runtime. This must fail the build.
#   exit 1 = ADVISORY. Skills that declare no allowed-tools at all. They inherit
#            the full tool set, so they cannot be broken by this check. Gating on
#            this would redden every PR until an unrelated backlog is burned
#            down, which is how a gate gets commented out.
#   exit 3 = MISCONFIGURED. The audit could not find the skills tree. A scan that
#            measures nothing must never read as a pass.
#
# Registered in tests/run-all-tests.sh. The audit itself was unreferenced by any
# runner for its whole life, so it had never once executed in CI.

set -euo pipefail
trap 'echo "[$0] failed at line $LINENO" >&2' ERR

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
AUDIT="$SCRIPT_DIR/audit-skill-permissions.sh"

if [[ ! -f "$AUDIT" ]]; then
    echo "FATAL: audit script not found at $AUDIT" >&2
    exit 1
fi

# `|| rc=$?` keeps set -e happy while still capturing a non-zero status: a
# command on the left of || is not treated as an unhandled failure.
rc=0
bash "$AUDIT" || rc=$?

case "$rc" in
    0)
        echo "PASS: every declared allowed-tools covers the tools its body instructs."
        ;;
    1)
        echo "PASS (with advisory): no coverage violations. Some skills declare no"
        echo "allowed-tools at all; they are unconstrained, so this is a backlog"
        echo "signal rather than a defect."
        ;;
    2)
        echo "FAIL: a skill instructs a tool its allowed-tools does not permit." >&2
        echo "Fix by adding the tool to allowed-tools, removing the call-shaped" >&2
        echo "example, or, for a pure reference skill, marking the body with" >&2
        echo "<!-- tool-coverage: illustrative -->." >&2
        exit 1
        ;;
    3)
        echo "FAIL: the audit could not locate the skills tree, so it measured" >&2
        echo "nothing. Treating that as a pass would be the exact defect this" >&2
        echo "gate exists to catch." >&2
        exit 1
        ;;
    *)
        echo "FAIL: unexpected exit code $rc from the audit." >&2
        exit 1
        ;;
esac
